import {NPCS} from '../data/config.js';
/** Platform services return explicit unavailable responses; never imitate a real ad or charge. */
export class AdsService {available=false;test=false;async showRewarded(){return {completed:false,available:false};}}
export class PurchaseService {available=false;test=false;async purchase(){return {purchased:false,available:false};}}
export class CloudSaveService {async load(){return null;}async save(){return {available:false};}}
export class AnalyticsService {constructor(){this.events=[];}track(event,details={}){this.events.push({event,details});if(this.events.length>100)this.events.shift();}}
export class LeaderboardService {list(s,mode='wealth'){return [...NPCS,{id:'you',name:'you',level:s.level,wealth:s.stats.earned}].sort((a,b)=>b[mode]-a[mode]);}}
export class SoundManager {constructor(){this.ctx=null;this.musicTimer=null;}tone(type='click'){try{this.ctx??=new (globalThis.AudioContext||globalThis.webkitAudioContext)();this.ctx.resume().catch(()=>{});const patterns={click:[360],money:[523.25,783.99],purchase:[392,523.25,659.25],level:[392,493.88,587.33,783.99],achievement:[523.25,659.25,880],unlock:[329.63,493.88,659.25]};(patterns[type]||patterns.click).forEach((f,i)=>{const o=this.ctx.createOscillator(),g=this.ctx.createGain(),t=this.ctx.currentTime+i*.09;o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(type==='click'?.018:.035,t);g.gain.exponentialRampToValueAtTime(.001,t+.18);o.connect(g);g.connect(this.ctx.destination);o.start(t);o.stop(t+.2);});}catch{}}
music(on){if(this.musicTimer){clearInterval(this.musicTimer);this.musicTimer=null;}if(on){let n=0;this.musicTimer=setInterval(()=>{if(globalThis.document?.hidden)return;try{this.ctx??=new AudioContext();const o=this.ctx.createOscillator(),g=this.ctx.createGain(),t=this.ctx.currentTime;o.frequency.value=[130.81,164.81,196,146.83][n++%4];g.gain.setValueAtTime(.015,t);g.gain.exponentialRampToValueAtTime(.001,t+1.5);o.connect(g);g.connect(this.ctx.destination);o.start();o.stop(t+1.6);}catch{}},1800);}}}
